def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Each straight 5-line is a seed axis. Extend its neighboring color
    # sequence across the empty cells parallel to that axis.
    # Horizontal seed run: colored markers immediately below its first cell
    # give the row colors to extend along the run.
    for r in range(h):
        runs=[]; j=0
        while j<w:
            if grid[r][j]==5:
                k=j
                while k+1<w and grid[r][k+1]==5:k+=1
                if k>j:runs.append((j,k))
                j=k+1
            else:j+=1
        for a,b in runs:
            for rr in range(r+1,h):
                if grid[rr][a] not in (0,5):
                    for cc in range(a,b+1):
                        if grid[rr][cc]==0:out[rr][cc]=grid[rr][a]
    # Vertical seed run: colored template to its right at the end repeats upward/downward.
    for c in range(w):
        rows=[r for r in range(h) if grid[r][c]==5]
        if len(rows)<2: continue
        if rows!=list(range(min(rows),max(rows)+1)): continue
        hi=max(rows); lo=min(rows)
        templates=[]
        for rr in range(max(0,hi-1),min(h,hi+1)):
            vals=[grid[rr][cc] for cc in range(c+1,w) if grid[rr][cc]!=0]
            if vals:templates.append(vals)
        if templates:
            for rr in rows:
                vals=templates[(rr-lo)%len(templates)]
                for k,v in enumerate(vals):
                    if c+1+k<w:out[rr][c+1+k]=v
    # Vertical color key next to a horizontal bar fills rowwise (including seed markers).
    for r in range(h):
        cols=[c for c in range(w) if grid[r][c]==5]
        if len(cols)>1:
            a=min(cols);b=a
            while b+1<w and grid[r][b+1]==5:b+=1
            for rr in range(r+1,h):
                if grid[rr][a] not in (0,5):
                    for cc in range(a,b+1):
                        if grid[rr][cc]!=5:out[rr][cc]=grid[rr][a]
    return out
